package com.bank.analytics;

import java.math.BigDecimal;
import java.util.Arrays;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class OccurrenceCountDemo {
    private static final Logger log = Logger.getLogger(OccurrenceCountDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        List<BigDecimal> amounts = Arrays.asList(
            new BigDecimal("5000.00"),
            new BigDecimal("1200.00"),
            new BigDecimal("5000"),      // same value, different scale
            new BigDecimal("300.00"),
            new BigDecimal("5000.00"));

        Account rajesh = new Account("SAV2001", "Rajesh Kumar", amounts);
        TransactionCounter counter = new TransactionCounter();

        BigDecimal target = new BigDecimal("5000");
        int count = counter.countOccurrences(rajesh.getAmounts(), target);
        log.info(() -> "Rs." + target + " debited " + count + " times for "
                + rajesh.getHolderName() + " (" + rajesh.getAccountId() + ")");
    }
}

class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
