package com.bank.analytics;

import java.math.BigDecimal;
import java.util.List;

class TransactionCounter {

    // O(n) scan: tally every element equal (by value) to the target.
    int countOccurrences(List<BigDecimal> amounts, BigDecimal target) {
        if (amounts == null) {
            throw new IllegalArgumentException("amounts must not be null");
        }
        int count = 0;
        for (BigDecimal current : amounts) {
            if (target.compareTo(current) == 0) {   // value equality, ignores scale
                count++;                             // tally a match
            }
        }
        return count;
    }
}
